/**
 * Optimized Pixel Art Grid Visualizer
 * Fixes recursion lag caused by multiple draw loops
 */

const GRID_W = 9;
const GRID_H = 6;
const TOTAL_PIXELS = GRID_W * GRID_H;

// 1. Settings definition
settings.define([
  { key: 'bg', label: 'Background', type: 'color', default: '#121212' },
  { key: 'color0', label: 'Color 0 (Red)', type: 'color', default: '#ED1C24' },
  { key: 'color1', label: 'Color 1 (White)', type: 'color', default: '#FFFFFF' },
  { key: 'color2', label: 'Color 2 (Blue)', type: 'color', default: '#242A56' }
]);

// 2. Setup Ports
setPortCount(1, 0);

// 3. State Management
let pixelBuffer = new Array(TOTAL_PIXELS).fill(0);

// Message handling - Only updates data, DOES NOT trigger draw
recv((data) => {
  if (Array.isArray(data)) {
    if (data.length === TOTAL_PIXELS) {
      // Faster than spreading for fixed size
      for(let i=0; i<TOTAL_PIXELS; i++) pixelBuffer[i] = data[i];
    } else {
      // Partial update / Stream
      for (const val of data) {
        pixelBuffer.push(val);
        if (pixelBuffer.length > TOTAL_PIXELS) pixelBuffer.shift();
      }
    }
  } else if (typeof data === 'number') {
    pixelBuffer.push(data);
    if (pixelBuffer.length > TOTAL_PIXELS) pixelBuffer.shift();
  } else if (data && data.type === 'bang') {
    pixelBuffer.fill(0);
  }
});

function render() {
  // Cache settings values once per frame for better performance
  const bgColor = settings.get('bg');
  const palette = [
    settings.get('color0'),
    settings.get('color1'),
    settings.get('color2')
  ];

  // Clear background
  ctx.fillStyle = bgColor;
  ctx.fillRect(0, 0, width, height);

  const cellW = width / GRID_W;
  const cellH = height / GRID_H;

  // Batch drawing operations
  for (let i = 0; i < TOTAL_PIXELS; i++) {
    const x = i % GRID_W;
    const y = Math.floor(i / GRID_W);
    const val = pixelBuffer[i];

    // Fallback to dark grey if color index is missing
    ctx.fillStyle = palette[val] || '#333333';

    // Drawing with integer alignment to prevent blur/gaps
    ctx.fillRect(
      Math.floor(x * cellW),
      Math.floor(y * cellH),
      Math.ceil(cellW),
      Math.ceil(cellH)
    );
  }

  // Loop efficiently
  requestAnimationFrame(render);
}

// Start the loop once
render();
